floor_fn:
"""
    Move a tile. This returns a moved copy; the original is unchaged.

    Parameters
    ----------
    tile : tuple
        containing y and x slice objects
    offset : tuple
        translation, given as ``(y, x)``

    Returns
    -------
    tile : tuple
        a copy; the input is unchaged
    """
def translate(tile: Any, offset: Any) -> object {
    (dy, dx) = offset;
    (y, x) = tile;
    new_tile = (
        slice((y.start + dy), (y.stop + dy)),
        slice((x.start + dx), (x.stop + dx))
    );
    return new_tile;
}

test_blocks:
test "t0" {
    assert (
        translate((slice(5, 10), slice(15, 20)), (0, 0))
        == (slice(5, 10), slice(15, 20))
    );;
}

test "t1" {
    assert (
        translate((slice(0, 1), slice(0, 1)), (1, 1)) == (slice(1, 2), slice(1, 2))
    );;
}

test "t2" {
    assert (
        translate((slice(10, 12), slice(20, 25)), (0, 0))
        == (slice(10, 12), slice(20, 25))
    );;
}

test "t3" {
    assert (
        translate((slice(5, 10), slice(15, 20)), (1, 0))
        == (slice(6, 11), slice(15, 20))
    );;
}

test "t4" {
    assert (
        translate((slice(0, 2), slice(0, 2)), (0, 1)) == (slice(0, 2), slice(1, 3))
    );;
}

test "t5" {
    assert (
        translate((slice(2, 5), slice(2, 5)), (2, 2)) == (slice(4, 7), slice(4, 7))
    );;
}

test "t6" {
    assert (
        translate((slice(5, 10), slice(15, 20)), (0, 1))
        == (slice(5, 10), slice(16, 21))
    );;
}

test "t7" {
    assert (
        translate((slice(5, 10), slice(15, 20)), (1, 1))
        == (slice(6, 11), slice(16, 21))
    );;
}

test "t8" {
    assert (
        translate((slice(0, 2), slice(0, 2)), (1, 0)) == (slice(1, 3), slice(0, 2))
    );;
}

test "t9" {
    assert (
        translate((slice(0, 2), slice(0, 2)), (1, 1)) == (slice(1, 3), slice(1, 3))
    );;
}
